onLoad(e) {
	this.searchValue = e.searchVal || '';
	this.getSearchHotKeywords();
	this.getSearchRecommend();
	setTimeout(()=>{
		this.newPartySearch();
	},1000)
},
onShow: function(e) {
	uni.removeStorageSync('form_type_cart');
	this.searchList();

},
onPullDownRefresh() {
	this.getSearchHotKeywords();
	this.getSearchRecommend();
	this.searchList();
	setTimeout(()=> {
		this.newPartySearch();
		uni.stopPullDownRefresh();
	}, 1000);
},
onPageScroll(object) {
	uni.$emit('scroll');
},
methods: {
	refresh(){
		this.isSpin = true;
		this.getSearchHotKeywords();
	},
	// 获取搜索热词
	getSearchHotKeywords(){
		getHotWordApi().then(res=>{
			this.hotSearchList = res.data;
			setTimeout(_=>{
				this.isSpin = false;
			},1000)
		})

searchList() {
	searchList({
		page: 1,
		limit: 10
	}).then(res => {
		this.history = res.data;
	});
},
clear() {
	let that = this;
	clearSearch().then(res => {
		uni.showToast({
			title: res.msg,
			success() {
				that.history = [];
			}
		});
	});
},
inputConfirm: function(event) {
	if (event.detail.value) {
		uni.hideKeyboard();
		this.setHotSearchValue(event.detail.value);
	}
},
setValue: Debounce(function(e){
	this.newPartySearch();
}),
newPartySearch: function() {
	getSearchKeyword({keyword:this.searchValue}).then(res => {
		this.newPartyList = res.data.list;
		this.newPartyList.map((item) => {
			this.$set(item,'keyword',this.brightKeyword(item.store_name,res.data.keyword));
		});
	});
},
brightKeyword(val,keyword) {
	if (val.indexOf(keyword) > -1) {
		val = `<p class="line1">${val}</p>`
		return val.replace(keyword, `<span style="color: #C9771E;">${keyword}</span>`);
	} else {

		return val;
	}
},
setCommentSearch(id) {
	uni.navigateTo({
		url:'/pages/goods/goods_list/index?productId=' + id
	})
},
setHotSearchValue: function(event) {
	this.$set(this, 'searchValue', event);
	this.focus = false;
	this.searchBut();
},
searchBut: function() {
	let that = this;
	that.focus = false;
	if (that.searchValue.length > 0) {
		this.newPartyList = [];
		uni.navigateTo({
			url:'/pages/goods/goods_list/index?searchValue=' + that.searchValue
		})
	} else {
		return this.$util.Tips({
			title: '请输入要搜索的商品',
			icon: 'none',
			duration: 1000,
			mask: true,
		});
	}

/**
 * 获取搜索关键字获取
 * 
 */
export function getSearchKeyword(data) {
	return request.get('search/keyword', data, {
		noAuth: true
	});
}

/**
 * 获取搜索关键字获取
 * 
 */
export function getHotWordApi() {
	return request.get('search/hot_keyword', {}, {
		noAuth: true
	});
}

/**
 * 搜索热词：用户搜索记录
 * @param StoreProductWordsServices $wordsServices
 * @return \think\Response
 */
public function hotKeywords(StoreProductWordsServices $wordsServices)
{
    [$page, $limit] = $wordsServices->getPageValue();
    return app('json')->success($wordsServices->getList(['is_show' => 1, 'is_del' => 0], 'id,name,color,bg_color,border_color,icon', $page, $limit));
}

/**
 * 搜索关键字关联

public function getList(array $where, string $field = '*', int $page = 0, int $limit = 0)
{
    return $this->search($where)->field($field)
        ->when($page && $limit, function ($query) use ($page, $limit) {
            $query->page($page, $limit);
        })->order('sort desc,id desc')->select()->toArray();

getPic(pic) {
  this.modalPic = false;
  this.form.icon = pic.att_dir;
},
delImage(){
  this.form.icon = '';
},
addWordsConfirm(){
  this.$refs.form.validate((valid) => {
    if (valid){
      hotWordsAddApi(this.isEdit ? this.word_id : 0,this.form).then(res=>{
        this.$Message.success(res.msg);
        this.modals = false;
        this.cancel();
        this.hotWordsForm.page = 1;
        this.getList();
      }).catch((res) => {
        this.$Message.error(res.msg);
      });
    }
  })
},
cancel(){
  this.form = {
    name: '',
    color: '#4f4f4f',
    bg_color: '#f4f4f4',
    border_color:'',
    sort: 0,
    is_show: 1,
    icon: '',
    is_search: 0,

