    sha256: string;
    rootRouteSources?: Array<{ file: string; sha256: string }>;
    registeredRoutes: Array<{
      source?: string;
      method: string;
      path: string;
      line: number;
      handler: string;
      availability: "executable" | "controlled_unavailable";
    }>;
  };
  frontendSources: Array<{ file: string; sha256: string }>;
  counts: {
    callSites: number;
    pathVariants: number;
    registered: number;
    executable: number;
    controlledUnavailable: number;
    unregistered: number;
    unresolved: number;
  };
